"""Real multipart XML 4.4 upload, supplier/SKU mapping and once-only reception."""
import hashlib,json,pathlib,secrets,subprocess,sys
sys.path.insert(0,'/workspace/fisitaap-env/tests')
from r3_helpers import request,csrf,sql
checks=[]
def passed(x):checks.append(x);print('PASS',x,flush=True)
def xml(invoice,tax,lines):
    rows=''.join('<LineaDetalle><CodigoComercial><Tipo>01</Tipo><Codigo>'+sku+'</Codigo></CodigoComercial><Cantidad>'+str(qty)+'</Cantidad><Detalle>Artículo QA</Detalle><PrecioUnitario>'+str(cost)+'</PrecioUnitario><Impuesto><Monto>'+str(round(qty*cost*.13,2))+'</Monto></Impuesto></LineaDetalle>' for sku,qty,cost in lines)
    total=sum(qty*cost*1.13 for _,qty,cost in lines)
    return '<FacturaElectronica xmlns="https://cdn.comprobanteselectronicos.go.cr/xml-schemas/v4.4/facturaElectronica"><NumeroConsecutivo>'+invoice+'</NumeroConsecutivo><Emisor><Nombre>Emisor QA '+invoice+'</Nombre><Identificacion><Numero>'+tax+'</Numero></Identificacion></Emisor><DetalleServicio>'+rows+'</DetalleServicio><ResumenFactura><CodigoTipoMoneda><CodigoMoneda>CRC</CodigoMoneda></CodigoTipoMoneda><TotalComprobante>'+str(round(total,2))+'</TotalComprobante></ResumenFactura></FacturaElectronica>'
def upload(text):
    subprocess.run(['docker','exec','-i','fisitaap-r2-web','php','-r',"file_put_contents('/tmp/fisitaap-xml180.xml',stream_get_contents(STDIN));"],input=text.encode(),capture_output=True,check=True)
    p=subprocess.run(['docker','exec','fisitaap-r2-web','curl','--noproxy','*','-sS','-b','/tmp/r3-owner.cookies','-c','/tmp/r3-owner.cookies','-F','action=preview','-F','csrf='+csrf('owner','/admin/compras'),'-F','xml=@/tmp/fisitaap-xml180.xml;type=application/xml','http://localhost/admin/compras'],capture_output=True,check=True)
    return request('owner','/admin/compras?xml=1')[1]
def save(text,extra):
    key=hashlib.sha256(text.encode()).hexdigest();data={'csrf':csrf('owner','/admin/compras'),'action':'save-draft','purchase_key':key,'xml':1,'credit':1,'amount_paid':0,'due_date':'2027-01-01','payment_method':'Efectivo','account_id':0,**extra};request('owner','/admin/compras',data);return key,sql('SELECT * FROM fisitaap_purchase_drafts180 WHERE operation_key=?',[key])
def apply(draft):return request('owner','/admin/compras',{'csrf':csrf('owner','/admin/compras'),'action':'apply','id':draft['id'],'revision':draft['revision'],'confirm':'yes'})
def main():
    tag=secrets.token_hex(5);text=xml('XML-'+tag,'3101987654',[('QA1',2,150)]);stock=float(sql('SELECT quantity FROM product_inventory WHERE branch_id=301 AND product_id=501')[0]['quantity']);before=len(sql('SELECT id FROM suppliers WHERE tenant_id=101'));page=upload(text);assert 'Costo actual' in page and 'Diferencia' in page and 'QA1' in page
    key,rows=save(text,{'mapping[0]':501});assert len(rows)==1,request('owner','/admin/compras?xml=1')[1][-250:];data=json.loads(rows[0]['data']);assert data['supplier_id']==sql('SELECT id FROM suppliers WHERE tenant_id=101 AND tax_id="3-101-987654"')[0]['id'];assert len(sql('SELECT id FROM suppliers WHERE tenant_id=101'))==before;assert float(sql('SELECT quantity FROM product_inventory WHERE branch_id=301 AND product_id=501')[0]['quantity'])==stock;assert not sql('SELECT purchase_id id FROM fisitaap_r2_purchase_keys WHERE tenant_id=101 AND purchase_key=?',[key]);passed('XML 4.4 multipart upload detects an existing supplier by normalized ID and saves a mapped-SKU draft without stock or debt effects')
    apply(rows[0]);apply(rows[0]);assert float(sql('SELECT quantity FROM product_inventory WHERE branch_id=301 AND product_id=501')[0]['quantity'])==stock+2;purchase=sql('SELECT p.id,p.total FROM purchases p JOIN fisitaap_r2_purchase_keys k ON k.purchase_id=p.id WHERE k.tenant_id=101 AND k.purchase_key=?',[key]);assert len(purchase)==1 and purchase[0]['total']=='339.00';assert sql('SELECT balance FROM accounts_payable WHERE purchase_id=?',[purchase[0]['id']])[0]['balance']=='339.00';passed('applying the XML receives stock, new cost and payable exactly once across a retry')
    sku='XMLNEW-'+tag;tax='310'+str(secrets.randbelow(1000000)).zfill(6);other=xml('XMLNEW-'+tag,tax,[(sku,3,50),('QA1',1,100)]);upload(other);extra={'create_supplier':1,'new_product[0]':1,'new[0][sku]':sku,'new[0][name]':'Producto XML '+tag,'new[0][category_id]':401,'new[0][price]':200,'new[0][tax_rate]':13,'new[0][initial_stock]':4,'mapping[1]':501}
    key,rows=save(other,extra);assert len(rows)==1;assert not sql('SELECT id FROM products WHERE tenant_id=101 AND sku=?',[sku]);assert len(sql('SELECT id FROM suppliers WHERE tenant_id=101 AND tax_id=?',[tax]))==1;apply(rows[0]);apply(rows[0]);pid=sql('SELECT id FROM products WHERE tenant_id=101 AND sku=?',[sku])[0]['id'];assert sql('SELECT quantity FROM product_inventory WHERE branch_id=301 AND product_id=?',[pid])[0]['quantity']=='7.000';assert sql('SELECT is_active FROM branch_products WHERE branch_id=301 AND product_id=?',[pid])[0]['is_active']==1;assert len(sql('SELECT purchase_id id FROM fisitaap_r2_purchase_keys WHERE tenant_id=101 AND purchase_key=?',[key]))==1;passed('an approved new XML supplier and missing SKU can be created alongside an existing product, with initial plus received stock and branch availability')
    first=xml('TABA-'+tag,'3101987654',[('QA1',1,100)]);second=xml('TABB-'+tag,'3101987654',[('QA1',1,200)]);upload(first);upload(second);key,rows=save(first,{'mapping[0]':501});assert not rows;assert 'XML cambió' in request('owner','/admin/compras?xml=1')[1];passed('a second-tab XML replacement cannot silently save a different invoice under the first invoice operation key')
    malicious='<!DOCTYPE compra [<!ENTITY x SYSTEM "https://example.invalid/never-contact">]><compra><numero>XXE</numero><proveedor>&x;</proveedor></compra>';page=upload(malicious);assert 'XML no permitido' in page;passed('external-entity XML is rejected before parsing or contacting an external endpoint')
    pathlib.Path('actualizaciones/1.8.0/QA-XML.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'environment':'real multipart HTTP plus PHP/MariaDB fictional invoices; no real suppliers or tax services'},indent=2)+'\n')
if __name__=='__main__':main()
